def get_all_districts():
    """Get all districts"""
    return [{"id": d["id"], "name": d["name"]} for d in MALAWI_DISTRICTS]

def get_traditional_authorities(district_id):
    """Get traditional authorities for a district"""
    district = next((d for d in MALAWI_DISTRICTS if d["id"] == district_id), None)
    if district:
        return [{"id": ta["id"], "name": ta["name"]} for ta in district["traditional_authorities"]]
    return []

def get_villages(district_id, ta_id):
    """Get villages for a traditional authority"""
    district = next((d for d in MALAWI_DISTRICTS if d["id"] == district_id), None)
    if district:
        ta = next((t for t in district["traditional_authorities"] if t["id"] == ta_id), None)
        if ta:
            return [{"id": v, "name": v} for v in ta["villages"]]
    return []

def get_area_name(area_type, area_id):
    """Get the name of a predefined area"""
    if area_type == "district":
        district = next((d for d in MALAWI_DISTRICTS if d["id"] == area_id), None)
        return district["name"] if district else "Unknown"
    elif area_type == "traditional_authority":
        for district in MALAWI_DISTRICTS:
            ta = next((t for t in district["traditional_authorities"] if t["id"] == area_id), None)
            if ta:
                return f"{ta['name']}, {district['name']}"
        return "Unknown"
    elif area_type == "village":
        for district in MALAWI_DISTRICTS:
            for ta in district["traditional_authorities"]:
                if area_id in ta["villages"]:
                    return f"{area_id}, {ta['name']}, {district['name']}"
        return "Unknown"
    return "Unknown"

def get_district_boundaries():
    """Get all district boundary coordinates"""
    return MALAWI_DISTRICT_BOUNDARIES

def get_district_boundary(district_id):
    """Get boundary coordinates for a specific district"""
    return MALAWI_DISTRICT_BOUNDARIES.get(district_id, None)
